async function openTerminalSettings(){try{const t=await req('/api/payment-terminal/settings');modal('Integrações de pagamento',`<form id="terminal-form"><div class="field"><label>Marca / provedor</label><input name="provider" maxlength="100" value="${esc(t.provider||'')}" placeholder="Ex.: marca da maquininha" required></div><div class="field"><label>Identificação da máquina</label><input name="terminal_name" maxlength="100" value="${esc(t.terminal_name||'')}" placeholder="Ex.: Caixa 1"></div><div class="hint">Modo manual. Esta configuração não conecta a máquina nem guarda número de cartão, senha ou credencial. Para integração automática, será preciso validar o modelo e a API do provedor.</div><button class="btn">Salvar identificação</button></form>`);$('#terminal-form').onsubmit=async e=>{e.preventDefault();try{const result=await req('/api/payment-terminal/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();await openTerminalSummary();toast(result.connected?'Integração conectada':'Salvo em modo manual')}catch(err){toast(err.message)}}}catch(e){toast(e.message)}}
