async function openPixSettings(){
 try{
   const p=await req('/api/pix/settings');
   const providers=[['manual','Chave PIX sem integração automática'],['mercado_pago','Mercado Pago'],['nubank','Nubank'],['inter','Banco Inter'],['c6','Banco C6'],['itau','Itaú'],['bradesco','Bradesco'],['outro','Outro banco/provedor']];
   const options=providers.map(([value,label])=>`<option value="${value}" ${value===(p.provider||'manual')?'selected':''}>${label}</option>`).join('');
   modal('API / PIX · '+(state.company?.name||'empresa'),`<form id="pix-form"><p>As credenciais e a chave ficam vinculadas somente à empresa <b>${esc(state.company?.name||'selecionada')}</b>.</p><div class="field"><label>Banco ou provedor que recebe nesta loja</label><select name="provider" id="pix-provider">${options}</select></div><div class="field" id="pix-key-field"><label>Chave PIX manual (opcional quando a API estiver configurada)</label><input name="key" id="pix-key" value="${esc(p.key||'')}" maxlength="100"><small>Usada para montar um QR manual quando não houver Access Token.</small></div><div id="pix-manual-fields"><div class="field"><label>Nome do recebedor</label><input name="merchant_name" id="pix-merchant-name" maxlength="25" value="${esc(p.merchant_name||'')}"></div><div class="field"><label>Cidade</label><input name="merchant_city" id="pix-merchant-city" maxlength="15" value="${esc(p.merchant_city||'')}"></div></div><div id="pix-mp-fields"><div class="field"><label>Access Token privado do Mercado Pago para esta loja</label><input name="access_token" id="pix-access-token" type="password" autocomplete="new-password" maxlength="500" placeholder="${p.has_access_token?'Token salvo. Deixe vazio para manter.':'Cole aqui o Access Token privado desta conta'}"><small>Use o token privado da conta selecionada no Mercado Pago. Ele fica criptografado no servidor, não aparece nas respostas e não deve ser compartilhado por conversa.</small></div><label class="field pix-mp-clear"><input type="checkbox" name="clear_access_token" id="pix-clear-token"> Apagar o token salvo desta empresa</label><div class="pix-mp-message">${p.has_access_token?'Access Token salvo para esta empresa. A credencial será validada ao criar uma cobrança.':'Ainda não há Access Token salvo para esta empresa. Cada loja precisa cadastrar a credencial da própria conta.'}</div></div><div class="pix-manual-status"><strong id="pix-settings-mode">${p.automatic_ready?'TOKEN SALVO · VALIDAR NA COBRANÇA':'CONFERÊNCIA MANUAL / TOKEN PENDENTE'}</strong><span id="pix-settings-help">${p.automatic_ready?'O caixa criará uma cobrança específica e só registrará a venda depois que a API confirmar o crédito e o valor.':'Para Mercado Pago, informe o Access Token privado desta conta. Para os demais bancos, a conferência continua manual.'}</span></div><button class="btn">Salvar configuração desta loja</button></form>`);
   const provider=$('#pix-provider'),manual=$('#pix-manual-fields'),mp=$('#pix-mp-fields'),key=$('#pix-key'),keyField=$('#pix-key-field'),name=$('#pix-merchant-name'),city=$('#pix-merchant-city'),accessToken=$('#pix-access-token'),clearToken=$('#pix-clear-token');
   const sync=()=>{const mercado=provider.value==='mercado_pago';const hasToken=mercado&&((p.has_access_token&&!clearToken.checked)||!!accessToken.value.trim());const manualFallback=!mercado||!hasToken;manual.hidden=!manualFallback;manual.classList.toggle('hidden',!manualFallback);keyField.hidden=hasToken;keyField.classList.toggle('hidden',hasToken);mp.hidden=!mercado;mp.classList.toggle('hidden',!mercado);key.required=mercado?(!hasToken&&!key.value.trim()):true;name.required=manualFallback;city.required=manualFallback;$('#pix-settings-mode').textContent=hasToken?'TOKEN MERCADO PAGO SALVO/INFORMADO · VALIDAR NA COBRANÇA':mercado?'MERCADO PAGO · QR MANUAL':'CONFERÊNCIA MANUAL';$('#pix-settings-help').textContent=hasToken?'A cobrança será criada e consultada pela API. A venda só será registrada após confirmar o crédito do valor exato.':'Sem Access Token, o QR usa a chave da loja e continua em conferência manual no extrato.'};
   provider.onchange=sync;accessToken.oninput=()=>{if(accessToken.value.trim())clearToken.checked=false;sync()};clearToken.onchange=sync;key.oninput=sync;sync();
   $('#pix-form').onsubmit=async e=>{e.preventDefault();try{const payload=Object.fromEntries(new FormData(e.target));payload.clear_access_token=$('#pix-clear-token').checked;const result=await req('/api/pix/settings',{method:'PUT',body:JSON.stringify(payload)});closeModal();await openPixApiSummary();toast(result.automatic_ready?'API Mercado Pago salva nesta loja. Gere uma cobrança para validar a credencial.':'PIX salvo; a conferência continuará manual para este banco.')}catch(err){toast(err.message)}}
 }catch(err){toast(err.message)}
}
function reportDate(){return new Date().toLocaleString('pt-BR')}
function printDocument(title,headers,rows,foot='',existingWindow=null){const w=existingWindow||window.open('','_blank','width=850,height=760');if(!w){toast('O navegador bloqueou a janela. Permita pop-ups e tente novamente.');return}const receipt=title.startsWith('Comprovante de venda');const table=rows.length?`<table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p>Sem registros para este relatório.</p>';w.document.open();w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(title)}</title><style>${receipt?'@page{size:80mm auto;margin:3mm}body{max-width:74mm;margin:0 auto;font-size:11px!important}th,td{padding:5px 3px!important;word-break:break-word}h1{font-size:16px!important}':''}body{font:14px Arial,sans-serif;color:#152e48;margin:28px}header{border-bottom:3px solid #153b64;padding-bottom:14px;margin-bottom:24px}h1{font-size:22px;margin:0 0 8px}small{color:#64748b}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #ddd}th{background:#eff4fa}footer{margin-top:24px;font-weight:bold}@media print{body{margin:8mm}@page{size:auto;margin:10mm}}</style></head><body><header><strong>NYC.WEB.BR GESTÃO</strong><h1>${esc(title)}</h1><small>${esc(state.company?.name||'Empresa')} · ${esc(reportDate())}</small></header>${table}<footer>${esc(foot)}</footer></body></html>`);w.document.close();w.focus();setTimeout(()=>{try{w.print()}catch(err){toast('Não foi possível abrir a impressão. Use Ctrl+P na janela do comprovante.')}},350)}
function printStock(low){const arr=state.products.filter(p=>!low||Number(p.stock)<=Number(p.min_stock));printDocument(low?'Relatório de estoque baixo':'Relatório de estoque completo',['Código','Produto','Categoria','Unidade','Custo','Preço','Estoque','Mínimo'],arr.map(p=>[p.sku,p.name,p.category,p.unit,money(p.cost_price),money(p.sale_price),String(p.stock),String(p.min_stock)]),`${arr.length} produto(s) no relatório`)}
function printReceipt(sale,items,payment,printWindow=null){const rows=items.map(i=>[i.name,String(i.quantity),money(i.unit_price),money(i.quantity*i.unit_price)]);if(Number(sale.discount_total)>0)rows.push(['Desconto aplicado','','',money(-sale.discount_total)]);const verification=sale.pix_verification==='conferencia_manual'?' · PIX conferido manualmente pelo operador; não consultado pelo sistema':sale.pix_verification==='verificado_mercado_pago'?' · PIX confirmado pela API do Mercado Pago':'';printDocument(`Comprovante de venda #${sale.id}`,['Produto','Qtd.','Unitário','Subtotal'],rows,`Pagamento: ${payment} · Total: ${money(sale.total)}${verification} · Documento não fiscal`,printWindow)}
async function printCash(last){try{let c=state.cashSession;if(last){const history=await req('/api/cash/history');c=history.find(x=>x.status==='fechado');if(!c)return toast('Nenhum fechamento de caixa encontrado')}if(!c)return toast('Nenhum caixa aberto');const sales=await req('/api/sales?limit=500');const from=new Date(c.opened_at).getTime(),to=c.closed_at?new Date(c.closed_at).getTime():Date.now();const valid=sales.filter(x=>{const t=new Date(x.created_at).getTime();return t>=from&&t<=to&&x.status==='concluida'});const total=valid.reduce((sum,x)=>sum+Number(x.total),0);printDocument(last?'Fechamento de caixa':'Resumo do caixa',['Informação','Valor'],[['Abertura',new Date(c.opened_at).toLocaleString('pt-BR')],['Fechamento',c.closed_at?new Date(c.closed_at).toLocaleString('pt-BR'):'Em aberto'],['Fundo inicial',money(c.opening_amount)],['Vendas no período (até 500 recentes)',money(total)],['Valor contado',c.closing_amount==null?'Não informado':money(c.closing_amount)]],`Vendas encontradas: ${valid.length}. Conferir pagamentos por modalidade; relatório não substitui conciliação financeira.`)}catch(e){toast(e.message)}}
function findBarcode(){const code=$('#barcode-input')?.value.trim();if(!code)return toast('Informe o código de barras');const p=state.products.find(p=>String(p.barcode||'').trim()===code)||state.products.find(p=>String(p.sku).trim()===code);if(!p)return toast('Código não encontrado. Cadastre o EAN/GTIN no produto.');$('#sale-product').value=String(p.id);addProductToCart(p.id,1);$('#barcode-input').value='';toast('Produto adicionado: '+p.name)}
async function cameraScan(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Câmera de leitura indisponível neste navegador. Use leitor USB/Bluetooth ou digite o código.');return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.createElement('video');video.setAttribute('playsinline','');video.autoplay=true;video.muted=true;video.srcObject=stream;modal('Ler código de barras',`<div id="camera-box"></div><p class="hint">Aponte a câmera para o código. Requer HTTPS em celulares.</p><button class="btn light" data-close>Cancelar</button>`);$('#camera-box').append(video);await video.play();const detector=new BarcodeDetector();let stopped=false;const stop=()=>{stopped=true;stream?.getTracks().forEach(t=>t.stop())};const close=$('[data-close]');close?.addEventListener('click',stop);const interval=setInterval(async()=>{if(stopped||!document.contains(video)){clearInterval(interval);stop();return}try{const results=await detector.detect(video);if(results.length){$('#barcode-input').value=results[0].rawValue;stop();clearInterval(interval);closeModal();findBarcode()}}catch(_){}},450)}catch(e){stream?.getTracks().forEach(t=>t.stop());toast('Não foi possível abrir a câmera: '+e.message)}}
async function loadSalesHistory(){const el=$('#sales-history');if(!el)return;try{const rows=await req('/api/sales');el.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Nº</th><th>Data</th><th>Pagamento</th><th>Conferência PIX</th><th>Total</th></tr></thead><tbody>${rows.map(s=>`<tr><td>#${s.id}</td><td>${new Date(s.created_at).toLocaleString('pt-BR')}</td><td>${esc(s.payment_method)}</td><td>${s.pix_verification==='conferencia_manual'?'Manual pelo operador':s.pix_verification==='verificado_mercado_pago'?'API Mercado Pago':'—'}</td><td class="product-name">${money(s.total)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma venda registrada ainda.</div>'}catch(e){el.innerHTML=errorBox(e.message)}}
function pdv11Payment(value){const select=$('#sale-payment');if(!select)return;select.value=value;select.dispatchEvent(new Event('change'));document.querySelectorAll('[data-pay]').forEach(b=>b.classList.toggle('selected',b.dataset.pay===value));if(value==='Dinheiro')$('#pdv-received')?.focus()}
function renderPdv13Favorites(){const root=$('#pdv13-favorites');if(!root)return;const ids=JSON.parse(localStorage.getItem('nyc-pdv-favorites-'+state.company?.id)||'[]');const products=ids.map(id=>state.products.find(p=>p.id===id&&p.stock>0)).filter(Boolean);root.innerHTML=products.length?products.map(p=>`<button type="button" data-favorite-add="${p.id}">${esc(p.name)} <b>${money(p.sale_price)}</b></button>`).join(''):'<span>Marque produtos no catálogo para adicioná-los aqui.</span>';root.querySelectorAll('[data-favorite-add]').forEach(b=>b.onclick=()=>addProductToCart(Number(b.dataset.favoriteAdd),1))}
function togglePdv13Favorite(id){const key='nyc-pdv-favorites-'+state.company?.id;const ids=JSON.parse(localStorage.getItem(key)||'[]');const updated=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id].slice(0,12);localStorage.setItem(key,JSON.stringify(updated));renderPdv13Favorites();renderPdvCatalog($('#pdv-search')?.value||'')}
function suspendPdv13(){if(!cart.length)return toast('Não há itens para suspender');const key='nyc-pdv-hold-'+state.company?.id;const pending=JSON.parse(localStorage.getItem(key)||'[]');pending.push({id:Date.now(),created_at:new Date().toISOString(),items:cart.map(x=>({...x}))});localStorage.setItem(key,JSON.stringify(pending.slice(-20)));cart=[];renderCart();toast('Venda suspensa neste navegador')}
function resumePdv13(){if(cart.length)return toast('Limpe ou conclua o carrinho antes de recuperar uma venda');const key='nyc-pdv-hold-'+state.company?.id;const pending=JSON.parse(localStorage.getItem(key)||'[]');if(!pending.length)return toast('Nenhuma venda suspensa');const item=pending[pending.length-1];const restored=[];for(const x of item.items){const p=state.products.find(p=>p.id===x.product_id);if(!p||Number(p.stock)<x.quantity)return toast('Estoque insuficiente para recuperar '+x.name);restored.push({...x,unit_price:Number(p.sale_price)})}cart=restored;pending.pop();localStorage.setItem(key,JSON.stringify(pending));renderCart();toast('Venda recuperada')}
function pdv11Shortcut(key){if(state.page!=='sales')return;const actions={F2:()=>$('#pdv-search')?.focus(),F3:()=>$('#barcode-input')?.focus(),F4:()=>$('#sale-payment')?.focus(),F6:()=>pdv11Payment('Dinheiro'),F7:()=>pdv11Payment('PIX'),F8:()=>$('#pdv-clear')?.click(),F10:()=>suspendPdv13(),F11:()=>resumePdv13(),F9:()=>$('#finish-sale')?.click(),Escape:()=>go('dashboard')};if(actions[key])actions[key]()}
document.addEventListener('keydown',e=>{if(document.querySelector('.modal-backdrop'))return;if(state.page!=='sales'||!['F2','F3','F4','F6','F7','F8','F9','F10','F11','Escape'].includes(e.key))return;e.preventDefault();pdv11Shortcut(e.key)});
function initPdv11(){const full=$('#pdv11-full');if(full)full.onclick=()=>{const enabled=document.body.classList.toggle('pdv11-full');full.textContent=enabled?'▣ Sair da tela exclusiva':'⛶ Tela exclusiva';$('#barcode-input')?.focus()};$('#pdv11-exit')?.addEventListener('click',()=>go('dashboard'));document.querySelectorAll('[data-shortcut]').forEach(b=>b.onclick=()=>pdv11Shortcut(b.dataset.shortcut));document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>pdv11Payment(b.dataset.pay));pdv11Payment('Dinheiro')}

